local Config = {
    OriginalScript = "https://raw.githubusercontent.com/realkidhub/realkid/refs/heads/main/main.lua",
    NewName = "Bố Là Phx",
    -- Tùy chọn: Nếu muốn ưu tiên ID ảnh Roblox thay vì ảnh nhúng sẵn, điền vào đây
    CustomBgAssetId = "",
    CustomLogoAssetId = "",
    -- Độ trong suốt của các khung nền tối để lộ hình anime giống demo (0 = đặc, 1 = trong suốt)
    PanelTransparency = 0.42
}

-- Ảnh nền anime & logo tròn đã được nhúng trực tiếp (Base64) - Không cần link ảnh ngoài
local EMBEDDED_BG_B64 = ""
local EMBEDDED_LOGO_B64 = ""

-- =====================================================================
-- BỘ GIẢI MÃ BASE64 & NẠP ASSET CỤC BỘ CHO EXECUTOR
-- =====================================================================
local function Base64Decode(data)
    if crypt and type(crypt.base64decode) == "function" then
        local ok, res = pcall(crypt.base64decode, data)
        if ok and res and #res > 0 then return res end
    end
    if type(base64_decode) == "function" then
        local ok, res = pcall(base64_decode, data)
        if ok and res and #res > 0 then return res end
    end
    if base64 and type(base64.decode) == "function" then
        local ok, res = pcall(base64.decode, data)
        if ok and res and #res > 0 then return res end
    end
    if syn and syn.crypt and syn.crypt.base64 and type(syn.crypt.base64.decode) == "function" then
        local ok, res = pcall(syn.crypt.base64.decode, data)
        if ok and res and #res > 0 then return res end
    end

    -- Fallback thuần Luau (tương thích mọi Executor hỗ trợ bit32)
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for k = 1, #chars do
        lookup[string.byte(chars, k)] = k - 1
    end

    local out = {}
    local idx = 1
    local len = #data
    local bit32_band = bit32.band
    local bit32_rshift = bit32.rshift
    local str_byte = string.byte
    local str_char = string.char

    local i = 1
    while i <= len do
        local a = lookup[str_byte(data, i)]
        local b = lookup[str_byte(data, i + 1)]
        local c = lookup[str_byte(data, i + 2)]
        local d = lookup[str_byte(data, i + 3)]
        if a and b then
            local n = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
            local b1 = bit32_band(bit32_rshift(n, 16), 255)
            local b2 = bit32_band(bit32_rshift(n, 8), 255)
            local b3 = bit32_band(n, 255)
            if c and d then
                out[idx] = str_char(b1, b2, b3)
            elseif c then
                out[idx] = str_char(b1, b2)
            else
                out[idx] = str_char(b1)
            end
            idx = idx + 1
        end
        i = i + 4
    end
    return table.concat(out)
end

local getAssetFn = getcustomasset or getsynasset

local function LoadEmbeddedAsset(customAssetId, b64Data, fileName)
    if customAssetId and customAssetId ~= "" then
        return customAssetId
    end
    if type(writefile) == "function" and type(getAssetFn) == "function" then
        local ok, asset = pcall(function()
            local raw = Base64Decode(b64Data)
            if raw and #raw > 0 then
                writefile(fileName, raw)
                return getAssetFn(fileName)
            end
            return ""
        end)
        if ok and asset and asset ~= "" then
            return asset
        end
    end
    return ""
end

local BgImage = LoadEmbeddedAsset(Config.CustomBgAssetId, EMBEDDED_BG_B64, "bolaphx_anime_bg.jpg")
local LogoImage = LoadEmbeddedAsset(Config.CustomLogoAssetId, EMBEDDED_LOGO_B64, "bolaphx_avatar_logo.png")

-- =====================================================================
-- HỆ THỐNG ĐỔI TÊN, NỀN ANIME VÀ LOGO TỰ ĐỘNG
-- =====================================================================
local CoreGui = game:GetService("CoreGui")

local function ReplaceName(str)
    if type(str) ~= "string" or str == "" then return str end
    local res = str
    res = res:gsub("[Rr][Ee][Aa][LlDd][Kk][Ii][Dd]%s*[Hh][Uu][Bb]", Config.NewName)
    res = res:gsub("[Rr][Ee][Aa][LlDd][Kk][Ii][Dd]", Config.NewName)
    return res
end

local function MakeCircular(guiObj)
    if not guiObj:FindFirstChild("PhxCircleCorner") then
        local corner = Instance.new("UICorner")
        corner.Name = "PhxCircleCorner"
        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = guiObj
    end
end

local function StyleDarkPanel(obj)
    if (obj:IsA("Frame") or obj:IsA("ScrollingFrame")) and obj.Name ~= "PhxAnimeBg" then
        if obj.BackgroundTransparency < Config.PanelTransparency then
            local c = obj.BackgroundColor3
            -- Chỉ làm trong suốt các bảng nền tối/xám, giữ nguyên nút xanh (Click) & nút màu nổi
            if c.R < 0.28 and c.G < 0.28 and c.B < 0.34 then
                obj.BackgroundTransparency = Config.PanelTransparency
            end
        end
    end
end

local function TryReplaceLogo(img, mainFrame)
    if LogoImage == "" then return end
    if not (img:IsA("ImageLabel") or img:IsA("ImageButton")) then return end
    if img.Name == "PhxAnimeBg" or img:GetAttribute("PhxLogoApplied") then return end

    local sz = img.AbsoluteSize
    if sz.X < 20 or sz.Y < 20 then return end

    local isSquare = math.abs(sz.X - sz.Y) <= 12
    local isLogoSize = sz.X >= 22 and sz.X <= 80
    local lowerName = img.Name:lower()
    local isIconSkip = lowerName:find("search") or lowerName:find("find") or lowerName:find("close") or lowerName:find("min") or lowerName:find("arrow")

    local isTopLeft = false
    if mainFrame then
        local relX = img.AbsolutePosition.X - mainFrame.AbsolutePosition.X
        local relY = img.AbsolutePosition.Y - mainFrame.AbsolutePosition.Y
        isTopLeft = (relX >= -10 and relX <= 85 and relY >= -10 and relY <= 65)
    end

    local screenGui = img:FindFirstAncestorOfClass("ScreenGui")
    local isFloatingToggle = img:IsA("ImageButton") and (img.Parent == screenGui or (img.Parent and img.Parent.Parent == screenGui and sz.X <= 75))

    if isSquare and isLogoSize and not isIconSkip and (isTopLeft or isFloatingToggle) then
        img:SetAttribute("PhxLogoApplied", true)
        img.Image = LogoImage
        img.ImageColor3 = Color3.fromRGB(255, 255, 255)
        img.BackgroundTransparency = 1
        img.ScaleType = Enum.ScaleType.Crop
        MakeCircular(img)
    end
end

local StyledGuis = {}

local function ApplyAnimeTheme(screenGui)
    if not screenGui or StyledGuis[screenGui] then return end
    StyledGuis[screenGui] = true

    -- Tìm khung chính lớn nhất của menu
    local mainFrame = nil
    local maxArea = 0
    for _, child in ipairs(screenGui:GetDescendants()) do
        if child:IsA("Frame") or child:IsA("CanvasGroup") then
            local size = child.AbsoluteSize
            local area = size.X * size.Y
            if area > maxArea and size.X >= 340 and size.Y >= 200 then
                if not child:FindFirstChildOfClass("UIListLayout") and not child:FindFirstChildOfClass("UIGridLayout") then
                    maxArea = area
                    mainFrame = child
                end
            end
        end
    end

    if mainFrame and BgImage ~= "" and not mainFrame:FindFirstChild("PhxAnimeBg") then
        mainFrame.ClipsDescendants = true
        mainFrame.BackgroundTransparency = 0.85

        for _, child in ipairs(mainFrame:GetChildren()) do
            if child:IsA("GuiObject") and child.ZIndex <= 0 then
                child.ZIndex = 1
            end
        end

        local bg = Instance.new("ImageLabel")
        bg.Name = "PhxAnimeBg"
        bg.Size = UDim2.fromScale(1, 1)
        bg.Position = UDim2.fromScale(0, 0)
        bg.BackgroundTransparency = 1
        bg.Image = BgImage
        bg.ScaleType = Enum.ScaleType.Crop
        bg.Active = false
        bg.ZIndex = 0
        bg.Parent = mainFrame

        local parentCorner = mainFrame:FindFirstChildOfClass("UICorner")
        if parentCorner then
            local bgCorner = Instance.new("UICorner")
            bgCorner.CornerRadius = parentCorner.CornerRadius
            bgCorner.Parent = bg
        end

        for _, sub in ipairs(mainFrame:GetDescendants()) do
            StyleDarkPanel(sub)
        end

        -- Tự động áp dụng độ trong suốt khi chuyển qua các Tab khác (Farm, Server, PVP...)
        mainFrame.DescendantAdded:Connect(function(sub)
            task.defer(function()
                pcall(StyleDarkPanel, sub)
                pcall(TryReplaceLogo, sub, mainFrame)
            end)
        end)
    end

    -- Thay logo chữ R xanh (góc trên trái & nút bật/tắt menu)
    for _, img in ipairs(screenGui:GetDescendants()) do
        pcall(TryReplaceLogo, img, mainFrame)
    end

    screenGui.DescendantAdded:Connect(function(obj)
        task.defer(function()
            pcall(TryReplaceLogo, obj, mainFrame)
        end)
    end)
end

local function HookObject(obj)
    if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
        local function UpdateText()
            local newTxt = ReplaceName(obj.Text)
            if newTxt ~= obj.Text then
                obj.Text = newTxt
                local rootGui = obj:FindFirstAncestorOfClass("ScreenGui")
                if rootGui then
                    task.delay(0.35, function()
                        pcall(ApplyAnimeTheme, rootGui)
                    end)
                end
            end
        end

        UpdateText()
        obj:GetPropertyChangedSignal("Text"):Connect(UpdateText)
    end
end

local function WatchContainer(container)
    if not container then return end
    for _, obj in ipairs(container:GetDescendants()) do
        pcall(HookObject, obj)
    end
    container.DescendantAdded:Connect(function(obj)
        task.defer(function()
            pcall(HookObject, obj)
        end)
    end)
end

task.spawn(function()
    pcall(WatchContainer, CoreGui)
    if type(gethui) == "function" then
        pcall(WatchContainer, gethui())
    end
end)

-- =====================================================================
-- KÍCH HOẠT SCRIPT GỐC (GIỮ NGUYÊN 100% CHỨC NĂNG)
-- =====================================================================
loadstring(game:HttpGet(Config.OriginalScript))()
